from PIL import Image; import numpy as np, json, math; from pathlib import Path
out=Path(__file__).parent; points=[p['xy'] for v in json.loads((out/'e1-residual-repeat.json').read_text()) .values() for p in v['pixels']]; base=600*float(np.float32(.82)); c=base/9; ox=400-base/2; oy=300-base/2; quads=[{'cell':[x,y],'tile':tile,'rect':[math.trunc(ox+x*c),math.trunc(oy+(8-y)*c),math.trunc(ox+(x+1)*c)-math.trunc(ox+x*c),math.trunc(oy+(9-y)*c)-math.trunc(oy+(8-y)*c)]} for x,y,tile in [(5,4,7),(3,2,34),(4,2,26)]]; textures={q['tile']:np.asarray(Image.open('src/assets/textures/wall_main_'+str(q['tile'])+'.png').convert('RGBA')).astype(float) for q in quads}
rows=[{'pixel':[x,y],**q,'uv':[(x+.5-q['rect'][0])/q['rect'][2],(y+.5-q['rect'][1])/q['rect'][3]],'sample_xy':[(x+.5-q['rect'][0])*200/q['rect'][2]-.5,(y+.5-q['rect'][1])*200/q['rect'][3]-.5]} for x,y in points for q in quads if q['rect'][0]<=x<q['rect'][0]+q['rect'][2] and q['rect'][1]<=y<q['rect'][1]+q['rect'][3]]
[r.update((lambda u,v:{'texel_xy':[[int(math.floor(u)+dx),int(math.floor(v)+dy)] for dy in [0,1] for dx in [0,1]],'texels':[textures[r['tile']][min(199,max(0,math.floor(v)+dy)),min(199,max(0,math.floor(u)+dx))].tolist() for dy in [0,1] for dx in [0,1]],'weights':[(1-(u-math.floor(u)) if dx==0 else u-math.floor(u))*(1-(v-math.floor(v)) if dy==0 else v-math.floor(v)) for dy in [0,1] for dx in [0,1]]})(*r['sample_xy'])) for r in rows]
(out/'e2-literal-samples.json').write_text(json.dumps({'base':base,'root':[ox,oy,base,base],'quads':quads,'rows':rows},indent=2),encoding='utf8'); print(json.dumps({'root':[ox,oy,base,base],'quads':quads,'records':len(rows),'key_rows':[r for r in rows if r['pixel'] in [[428,321],[323,382]]]}))
